sys_script_include.script:
var ScheduleUtils = Class.create();
ScheduleUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

  validateSchedule: function() {
    var result = { valid: true, message: "" };

    var scheduleId = this.getParameter("sysparm_schedule");
    var user = gs.getUserID();

    if (!scheduleId) {
      result.valid = false;
      result.message = "Missing schedule parameter.";
      return JSON.stringify(result);
    }

    var sch = new GlideRecord("x_1805892_compan_0_schedule");
    if (!sch.get(scheduleId)) {
      result.valid = false;
      result.message = "Invalid training schedule.";
      return JSON.stringify(result);
    }

    var trainingId = sch.getValue("training");
    var instructor = sch.getValue("instructor");
    var maxParticipants = parseInt(sch.getValue("max_participants"), 10);
    var trainingDate = new GlideDateTime(sch.getValue("schedule_for"));

    if (user == instructor) {
      result.valid = false;
      result.message = "You are the instructor for this training and cannot enroll.";
      return JSON.stringify(result);
    }

    var now = new GlideDateTime();
    var limitDate = new GlideDateTime(trainingDate);
    limitDate.addDaysUTC(-1);
    if (now > limitDate) {
      result.valid = false;
      result.message = "You can only enroll up to one day before the training date.";
      return JSON.stringify(result);
    }

    var dup = new GlideRecord("x_1805892_compan_0_schedule");
    dup.addQuery("training", trainingId);
    dup.addQuery("schedule_for", sch.getValue("schedule_for"));
    dup.addQuery("sys_id", "!=", scheduleId);
    dup.query();
    if (dup.hasNext()) {
      result.valid = false;
      result.message = "A training for this course already exists on this date.";
      return JSON.stringify(result);
    }

    var existing = new GlideRecord("x_1805892_compan_0_enrollment");
    existing.addQuery("schedule", scheduleId);
    existing.addQuery("requested_for", user);
    existing.query();
    if (existing.hasNext()) {
      result.valid = false;
      result.message = "You are already enrolled in this training session.";
      return JSON.stringify(result);
    }

    var past = new GlideRecord("x_1805892_compan_0_enrollment");
    past.addQuery("training", trainingId);
    past.addQuery("requested_for", user);
    past.query();
    var count = 0;
    while (past.next()) count++;
    if (count >= 3) {
      result.valid = false;
      result.message = "You have already attended this training 3 times.";
      return JSON.stringify(result);
    }

    var occupied = new GlideAggregate("x_1805892_compan_0_enrollment");
    occupied.addQuery("schedule", scheduleId);
    occupied.addQuery("state", "IN", "1,3");
    occupied.addAggregate("COUNT");
    occupied.query();

    var totalOccupied = 0;
    if (occupied.next()) {
      totalOccupied = parseInt(occupied.getAggregate("COUNT"), 10);
    }

    if (totalOccupied >= maxParticipants) {
      result.valid = false;
      result.message =
        "This training has reached its maximum capacity (" +
        maxParticipants +
        " participants including pending approvals).";
      return JSON.stringify(result);
    }

    result.valid = true;
    result.message = "Enrollment is valid.";
    return JSON.stringify(result);
  },

  type: "ScheduleUtils"
});
